export const makeMp3State = () => {
    let mp3Info = null;
    // cbr  = constant bit rate
    let cbrMp3Info = null;
    return {
        getMp3Info: () => mp3Info,
        setMp3Info: (info) => {
            mp3Info = info;
        },
        getCbrMp3Info: () => cbrMp3Info,
        setCbrMp3Info: (info) => {
            cbrMp3Info = info;
        },
    };
};
